class Solution:
    def totalSteps(self, nums):
        stk = []  # (value, steps)
        ans = 0
        for x in nums:
            cur = 0
            while stk and stk[-1][0] <= x:
                cur = max(cur, stk[-1][1])
                stk.pop()
            if stk:
                cur += 1
            else:
                cur = 0
