class Solution:
    def minimumObstacles(self, grid):
        m, n = len(grid), len(grid[0])
        dist = [[float('inf')] * n for _ in range(m)]
        dist[0][0] = 0
        dq = deque([(0, 0, 0)])
        while dq:
            d, x, y = dq.popleft()
            if d > dist[x][y]:
                continue
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n:
                    nd = d + grid[nx][ny]
                    if nd < dist[nx][ny]:
                        dist[nx][ny] = nd
                        if grid[nx][ny] == 0:
                            dq.appendleft((nd, nx, ny))
                        else:
                            dq.append((nd, nx, ny))
        return dist[m-1][n-1]

class Solution:
    def maximumProfit(self, present, future, budget):
        n = len(present)
        dp = [0] * (budget + 1)
        for i in range(n):
            profit = future[i] - present[i]
            if profit > 0:
                for j in range(budget, present[i]-1, -1):
                    dp[j] = max(dp[j], dp[j-present[i]] + profit)
        return dp[budget]

class Solution:
    def minMaxGame(self, nums):
        while len(nums) > 1:
            new = []
            for i in range(len(nums) // 2):
                if i % 2 == 0:
                    new.append(min(nums[2*i], nums[2*i+1]))
                else:
                    new.append(max(nums[2*i], nums[2*i+1]))
            nums = new
