class Solution:
    def countSubarrays(self, nums, k):
        ans = 0
        left = 0
        cur_sum = 0
        for right in range(len(nums)):
            cur_sum += nums[right]
            while cur_sum * (right - left + 1) >= k:
                cur_sum -= nums[left]
                left += 1
            ans += right - left + 1
        return ans

