class Solution:
    def distributeCookies(self, cookies, k):
        self.ans = float('inf')
        dist = [0] * k
        def dfs(idx):
            if idx == len(cookies):
                self.ans = min(self.ans, max(dist))
                return
            if max(dist) >= self.ans:
                return
            for i in range(k):
                dist[i] += cookies[idx]
                dfs(idx + 1)
                dist[i] -= cookies[idx]
                if dist[i] == 0:
                    break
        dfs(0)
        return self.ans

