class Solution:
    def checkContradictions(self, equations, values):
        from collections import defaultdict
        graph = defaultdict(list)
        for i, (a, b) in enumerate(equations):
            graph[a].append((b, values[i]))
            graph[b].append((a, 1.0/values[i]))
        visited = {}
        def dfs(node, val):
            if node in visited:
                return abs(visited[node] - val) > 1e-5
            visited[node] = val
            for nei, w in graph[node]:
                if dfs(nei, val * w):
                    return True
            return False
        for node in graph:
            if node not in visited:
                if dfs(node, 1.0):
                    return True
        return False

