class Solution:
    def countPairs(self, n, edges):
        parent = list(range(n))
        size = [1] * n
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return
            if size[px] < size[py]:
                px, py = py, px
            parent[py] = px
            size[px] += size[py]
        for a, b in edges:
            union(a, b)
        components = []
        for i in range(n):
            if find(i) == i:
                components.append(size[i])
        ans = 0
        total = 0
        for s in components:
            ans += total * s
            total += s
        return ans

