from math import gcd
class Solution:
    def distinctSequences(self, n):
        MOD = 10**9 + 7
        if n == 1:
            return 6
        dp = [[0]*7 for _ in range(7)]
        for i in range(1, 7):
            for j in range(1, 7):
                if i != j and gcd(i, j) == 1:
                    dp[i][j] = 1
        for _ in range(n - 2):
            ndp = [[0]*7 for _ in range(7)]
            for last in range(1, 7):
                for sec in range(1, 7):
                    if dp[last][sec] == 0:
                        continue
                    for nxt in range(1, 7):
                        if nxt != last and nxt != sec and gcd(nxt, last) == 1:
                            ndp[nxt][last] = (ndp[nxt][last] + dp[last][sec]) % MOD
            dp = ndp
        return sum(dp[i][j] for i in range(1,7) for j in range(1,7)) % MOD

