class Solution:
    def maximumsSplicedArray(self, nums1, nums2):
        def solve(a, b):
            # max sum of a after swapping a subarray with b
            total = sum(a)
            cur_gain = 0
            max_gain = 0
            for x, y in zip(a, b):
                cur_gain += y - x
                if cur_gain < 0:
                    cur_gain = 0
                max_gain = max(max_gain, cur_gain)
            return total + max_gain
        return max(solve(nums1, nums2), solve(nums2, nums1))

