class Solution:
    def peopleAwareOfSecret(self, n, delay, forget):
        MOD = 10**9 + 7
        dp = [0] * (n + 1)
        dp[1] = 1
        for i in range(2, n+1):
            for j in range(i-forget+1, i-delay+1):
                if j >= 1:
                    dp[i] = (dp[i] + dp[j]) % MOD
