class Solution:
    def countPaths(self, grid):
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])
        memo = {}
        def dfs(i, j):
            if (i, j) in memo:
                return memo[(i, j)]
            res = 1
            for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] > grid[i][j]:
                    res = (res + dfs(ni, nj)) % MOD
            memo[(i, j)] = res
            return res
        return sum(dfs(i, j) for i in range(m) for j in range(n)) % MOD

class Solution:
    def makePalindrome(self, s):
        mismatches = 0
        l, r = 0, len(s) - 1
        while l < r:
            if s[l] != s[r]:
                mismatches += 1
            if mismatches > 2:
                return False
            l += 1
