class Solution:
    def latestTimeCatchTheBus(self, buses, passengers, capacity):
        buses.sort()
        passengers.sort()
        ps = set(passengers)
        j = 0
        for bus in buses:
            cap = capacity
            while j < len(passengers) and passengers[j] <= bus and cap > 0:
                j += 1
                cap -= 1
        # Try to arrive at the latest possible time
        if cap > 0:
            ans = buses[-1]
        else:
            ans = passengers[j-1]
        while ans in ps:
            ans -= 1
        return ans

class Solution:
    def minSumSquareDiff(self, nums1, nums2, k1, k2):
        diff = [abs(a-b) for a, b in zip(nums1, nums2)]
        total_ops = k1 + k2
        if sum(diff) <= total_ops:
            return 0
        # Binary search for threshold
        lo, hi = 0, max(diff)
        while lo < hi:
            mid = (lo + hi) // 2
            ops_needed = sum(max(0, d - mid) for d in diff)
            if ops_needed <= total_ops:
                hi = mid
            else:
                lo = mid + 1
        # Apply threshold
        ops_used = sum(max(0, d - lo) for d in diff)
        remaining = total_ops - ops_used
        ans = 0
        for d in diff:
            nd = min(d, lo)
            if nd == lo and remaining > 0 and nd > 0:
                nd -= 1
                remaining -= 1
            ans += nd * nd
        return ans

class Solution:
    def validSubarraySize(self, nums, threshold):
        n = len(nums)
        left = [-1] * n
        right = [n] * n
        stk = []
        for i in range(n):
            while stk and nums[stk[-1]] >= nums[i]:
                right[stk.pop()] = i
            left[i] = stk[-1] if stk else -1
            stk.append(i)
        for i in range(n):
            k = right[i] - left[i] - 1
            if nums[i] > threshold / k:
                return k
        return -1

